WITH with_windows AS (SELECT *, FIRST_VALUE(country, TRUE) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_country, ROW_NUMBER() OVER (ORDER BY started_at DESC, id ASC) seq_no, LAST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY MONTH(started_at), device ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_browser FROM sessions WHERE customer_id IN (13, 14, 21)) SELECT s.id, s.customer_id, s.browser, s.country, s.first_known_country, s.seq_no, s.last_known_browser, (SELECT SUM(t2.shipping_fee) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS sum_order_shipping_fee FROM with_windows s ORDER BY country DESC;
